function validate([s, locked]) {
  if (s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (locked.length !== s.length) return 's and locked must have the same length.';
  if (!/^[()]+$/.test(s)) return "s may contain only '(' and ')'.";
  if (!/^[01]+$/.test(locked)) return "locked may contain only '0' and '1'.";
  return null;
}

