function canBeValid(s, locked) {
  const n = s.length;
  if (n % 2 === 1) return false;

  let open = 0;
  for (let i = 0; i < n; i++) {
    if (locked[i] === '0' || s[i] === '(') {
      open++;
    } else {
      open--;
    }
    if (open < 0) return false;
  }

  let close = 0;
  for (let i = n - 1; i >= 0; i--) {
    if (locked[i] === '0' || s[i] === ')') {
      close++;
    } else {
      close--;
    }
    if (close < 0) return false;
  }
  return true;
}

