function canBeValid(s, locked) {
  const free = [];
  for (let i = 0; i < s.length; i++) if (locked[i] === '0') free.push(i);
  const isValid = chars => {
    let depth = 0;
    for (const c of chars) {
      depth += c === '(' ? 1 : -1;
      if (depth < 0) return false;
    }
    return depth === 0 && chars.length > 0;
  };
  for (let mask = 0; mask < (1 << free.length); mask++) {
    const chars = s.split('');
    free.forEach((pos, bit) => { chars[pos] = (mask >> bit) & 1 ? '(' : ')'; });
    if (isValid(chars)) return true;
  }
  return false;
}

