function generate(rand, size) {
  const n = size === 'large' ? 2 * (2000 + Math.floor(rand() * 2000)) : 1 + Math.floor(rand() * 12);
  const lockRate = 0.2 + rand() * 0.7;
  const chars = [];
  if (n % 2 === 0 && rand() < 0.6) {
    // Build a valid string first, so that a true answer is common.
    let depth = 0;
    for (let i = 0; i < n; i++) {
      const left = n - i;
      const canOpen = depth < left - 1;
      const goOpen = depth === 0 || (canOpen && rand() < 0.5);
      chars.push(goOpen ? '(' : ')');
      depth += goOpen ? 1 : -1;
    }
  } else {
    for (let i = 0; i < n; i++) chars.push(rand() < 0.5 ? '(' : ')');
  }
  let locked = '';
  for (let i = 0; i < n; i++) {
    const isLocked = rand() < lockRate;
    locked += isLocked ? '1' : '0';
    if (!isLocked && rand() < 0.5) chars[i] = chars[i] === '(' ? ')' : '(';
  }
  // Occasionally break one locked character so that a false answer is also common.
  if (rand() < 0.3) {
    const i = Math.floor(rand() * n);
    if (locked[i] === '1') chars[i] = chars[i] === '(' ? ')' : '(';
  }
  return [chars.join(''), locked];
}
